fn original_android_defined_name_writer_and_partial_xml(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/defined-name-writer-r0b58");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let actual=json!({"cases":input["cases"].as_array().unwrap().iter().map(|p|one(&book,p)).collect::<Vec<_>>()});*CUR_VERSION.lock().unwrap()=SpreadsheetVersion::EXCEL2007;RendererOption::destroy();std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
